from solution import tn_gp


def test_issue_example():
    """Example assert tn_gp(1,5,2)==16."""
    assert tn_gp(1, 5, 2) == 16  # 1*2**4 = 1*16 = 16


def test_issue_first_term():
    """n-th term of geometric series with n=1 equals a."""
    assert tn_gp(5, 1, 3) == 5  # 5*3**0 = 5*1 = 5


def test_issue_second_term():
    """n-th term of geometric series with n=2 equals a*r."""
    assert tn_gp(3, 2, 4) == 12  # 3*4**1 = 3*4 = 12


def test_issue_ratio_one():
    """n-th term of geometric series with r=1 equals a."""
    assert tn_gp(7, 10, 1) == 7  # 7*1**9 = 7*1 = 7


def test_issue_ratio_zero_later():
    """n-th term of geometric series with r=0 and n>1 equals 0."""
    assert tn_gp(5, 3, 0) == 0  # 5*0**2 = 5*0 = 0


def test_issue_ratio_zero_first():
    """n-th term of geometric series with n=1 equals a even if r=0."""
    assert tn_gp(5, 1, 0) == 5  # first term is a = 5


def test_issue_negative_ratio():
    """n-th term of geometric series follows a*r**(n-1) for negative r."""
    assert tn_gp(2, 4, -3) == -54  # 2*(-3)**3 = 2*-27 = -54


def test_issue_zero_first_term():
    """n-th term of geometric series with a=0 equals 0."""
    assert tn_gp(0, 4, 5) == 0  # 0*5**3 = 0*125 = 0


def test_issue_fractional_ratio():
    """n-th term of geometric series follows a*r**(n-1) for fractional r."""
    assert tn_gp(8, 4, 0.5) == 1.0  # 8*0.5**3 = 8*0.125 = 1.0


def test_issue_tenth_term():
    """n-th term of geometric series with a=1, n=10, r=2 equals 512."""
    assert tn_gp(1, 10, 2) == 512  # 1*2**9 = 1*512 = 512
